from collections import deque,Counter

def comps(grid):
    R,C=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c]==7 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          x,y=q.pop(); cells.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<R and 0<=ny<C and grid[nx][ny]!=7 and (nx,ny) not in seen:
              seen.add((nx,ny)); q.append((nx,ny))
        vals=Counter(grid[x][y] for x,y in cells)
        out.append((cells, (min(x for x,y in cells),min(y for x,y in cells),max(x for x,y in cells),max(y for x,y in cells)),vals))
    return out
